27	export const Footer: React.FC = () => {
28	  const uiState = useUIState();
29	  const config = useConfig();
30	  const settings = useSettings();
31	  const { vimEnabled, vimMode } = useVimMode();
32	
33	  const {
34	    model,
35	    targetDir,
36	    debugMode,
37	    branchName,
38	    debugMessage,
39	    corgiMode,
40	    errorCount,
41	    showErrorDetails,
42	    promptTokenCount,
43	    isTrustedFolder,
44	    terminalWidth,
45	    quotaStats,
46	  } = {
47	    model: uiState.currentModel,
48	    targetDir: config.getTargetDir(),
49	    debugMode: config.getDebugMode(),
50	    branchName: uiState.branchName,
51	    debugMessage: uiState.debugMessage,
52	    corgiMode: uiState.corgiMode,
53	    errorCount: uiState.errorCount,
54	    showErrorDetails: uiState.showErrorDetails,
55	    promptTokenCount: uiState.sessionStats.lastPromptTokenCount,
56	    isTrustedFolder: uiState.isTrustedFolder,
57	    terminalWidth: uiState.terminalWidth,
58	    quotaStats: uiState.quota.stats,
59	  };
60	
61	  const showMemoryUsage =
62	    config.getDebugMode() || settings.merged.ui.showMemoryUsage;
63	  const hideCWD = settings.merged.ui.footer.hideCWD;
64	  const hideSandboxStatus = settings.merged.ui.footer.hideSandboxStatus;
65	  const hideModelInfo = settings.merged.ui.footer.hideModelInfo;
66	  const hideContextPercentage = settings.merged.ui.footer.hideContextPercentage;
67	
68	  const pathLength = Math.max(20, Math.floor(terminalWidth * 0.25));
69	  const displayPath = shortenPath(tildeifyPath(targetDir), pathLength);
70	
71	  const justifyContent = hideCWD && hideModelInfo ? 'center' : 'space-between';
72	  const displayVimMode = vimEnabled ? vimMode : undefined;
73	
74	  const showDebugProfiler = debugMode || isDevelopment;
75	
76	  return (
77	    <Box
78	      justifyContent={justifyContent}
79	      width={terminalWidth}
80	      flexDirection="row"
81	      alignItems="center"
82	      paddingX={1}
83	    >
84	      {(showDebugProfiler || displayVimMode || !hideCWD) && (
85	        <Box>
86	          {showDebugProfiler && <DebugProfiler />}
87	          {displayVimMode && (
88	            <Text color={theme.text.secondary}>[{displayVimMode}] </Text>
89	          )}
90	          {!hideCWD && (
91	            <Text color={theme.text.primary}>
92	              {displayPath}
93	              {branchName && (
94	                <Text color={theme.text.secondary}> ({branchName}*)</Text>
95	              )}
96	            </Text>
97	          )}
98	          {debugMode && (
99	            <Text color={theme.status.error}>
100	              {' ' + (debugMessage || '--debug')}
101	            </Text>
102	          )}
103	        </Box>
104	      )}
105	
106	      {/* Middle Section: Centered Trust/Sandbox Info */}
107	      {!hideSandboxStatus && (
108	        <Box
109	          flexGrow={1}
110	          alignItems="center"
111	          justifyContent="center"
112	          display="flex"
113	        >
114	          {isTrustedFolder === false ? (
115	            <Text color={theme.status.warning}>untrusted</Text>
116	          ) : process.env['SANDBOX'] &&
117	            process.env['SANDBOX'] !== 'sandbox-exec' ? (
118	            <Text color="green">
119	              {process.env['SANDBOX'].replace(/^gemini-(?:cli-)?/, '')}
120	            </Text>
121	          ) : process.env['SANDBOX'] === 'sandbox-exec' ? (
122	            <Text color={theme.status.warning}>
123	              macOS Seatbelt{' '}
124	              <Text color={theme.text.secondary}>
125	                ({process.env['SEATBELT_PROFILE']})
126	              </Text>
127	            </Text>
128	          ) : (
129	            <Text color={theme.status.error}>
130	              no sandbox
131	              {terminalWidth >= 100 && (
132	                <Text color={theme.text.secondary}> (see /docs)</Text>
133	              )}
134	            </Text>
135	          )}
136	        </Box>
137	      )}
138	
139	      {/* Right Section: Gemini Label and Console Summary */}
140	      {!hideModelInfo && (
141	        <Box alignItems="center" justifyContent="flex-end">
142	          <Box alignItems="center">
143	            <Text color={theme.text.primary}>
144	              <Text color={theme.text.secondary}>/model </Text>
145	              {getDisplayString(model)}
146	              {!hideContextPercentage && (
147	                <>
148	                  {' '}
149	                  <ContextUsageDisplay
150	                    promptTokenCount={promptTokenCount}
151	                    model={model}
152	                    terminalWidth={terminalWidth}
153	                  />
154	                </>
155	              )}
156	              {quotaStats && (
157	                <>
158	                  {' '}
159	                  <QuotaDisplay
160	                    remaining={quotaStats.remaining}
161	                    limit={quotaStats.limit}
162	                    resetTime={quotaStats.resetTime}
163	                    terse={true}
164	                  />
165	                </>
166	              )}
167	            </Text>
168	            {showMemoryUsage && <MemoryUsageDisplay />}
169	          </Box>
170	          <Box alignItems="center">
171	            {corgiMode && (
172	              <Box paddingLeft={1} flexDirection="row">
173	                <Text>
174	                  <Text color={theme.ui.symbol}>| </Text>
175	                  <Text color={theme.status.error}>▼</Text>
176	                  <Text color={theme.text.primary}>(´</Text>
177	                  <Text color={theme.status.error}>ᴥ</Text>
178	                  <Text color={theme.text.primary}>`)</Text>
179	                  <Text color={theme.status.error}>▼</Text>
180	                </Text>
181	              </Box>
182	            )}
183	            {!showErrorDetails && errorCount > 0 && (
184	              <Box paddingLeft={1} flexDirection="row">
185	                <Text color={theme.ui.comment}>| </Text>
186	                <ConsoleSummaryDisplay errorCount={errorCount} />
187	              </Box>
188	            )}
189	          </Box>
190	        </Box>
191	      )}
192	    </Box>
193	  );
194	};
